import type { ImageMetadata } from 'astro';

// Material swatches. Images live in src/assets/materials (generated by `npm run media` from the client folders).
const img = import.meta.glob<{ default: ImageMetadata }>('../assets/materials/*.jpg', { eager: true });
const photo = import.meta.glob<{ default: ImageMetadata }>('../assets/photos/*.jpg', { eager: true });
const m = (file: string) => (img[`../assets/materials/${file}.jpg`] ?? photo[`../assets/photos/${file}.jpg`]).default;

export type Kind = 'marble' | 'quartzite' | 'travertine';
export interface Material {
  id: string;
  name: string;
  kind: Kind;
  image: ImageMetadata;
  featured?: boolean;
  /** Short tonal description used in alt text (EN / ES / AR). */
  tone: { en: string; es: string; ar: string };
}

